// Blinky cho Tang Nano 20K (Gowin GW2AR-18C)
// Thạch anh 27 MHz, 6 LED tích cực thấp (0 = sáng)
module blinky (
    input  wire       clk,      // PIN 4, 27 MHz
    input  wire       btn_s1,   // PIN 88, nút S1, tích cực thấp
    output wire [5:0] led       // PIN 15-20, tích cực thấp
);

    reg [24:0] counter = 25'd0;
    reg [5:0]  led_reg = 6'b111110; // sáng 1 LED ban đầu (bit 0 = 0)

    always @(posedge clk or negedge btn_s1) begin
        if (!btn_s1) begin
            counter <= 25'd0;
            led_reg <= 6'b111110;
        end else begin
            if (counter >= 25'd13_500_000 - 1) begin // đảo mỗi 0,5 giây
                counter <= 25'd0;
                led_reg <= {led_reg[4:0], led_reg[5]}; // dịch vòng LED sáng
            end else begin
                counter <= counter + 1'b1;
            end
        end
    end

    assign led = led_reg;

endmodule

IO_LOC "clk" 4;
IO_PORT "clk" IO_TYPE=LVCMOS33 PULL_MODE=NONE;

IO_LOC "btn_s1" 88;
IO_PORT "btn_s1" IO_TYPE=LVCMOS33 PULL_MODE=UP;

IO_LOC "led[0]" 15;
IO_PORT "led[0]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

IO_LOC "led[1]" 16;
IO_PORT "led[1]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

IO_LOC "led[2]" 17;
IO_PORT "led[2]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

IO_LOC "led[3]" 18;
IO_PORT "led[3]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

IO_LOC "led[4]" 19;
IO_PORT "led[4]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

IO_LOC "led[5]" 20;
IO_PORT "led[5]" IO_TYPE=LVCMOS33 PULL_MODE=NONE DRIVE=8;

`timescale 1ns / 1ps
module tb_blinky;
    reg clk = 0;
    reg btn_s1 = 0;
    wire [5:0] led;

    blinky uut (
        .clk(clk),
        .btn_s1(btn_s1),
        .led(led)
    );

    always #18.5 clk = ~clk; // ~27 MHz (37.037 ns)

    initial begin
        #100;
        btn_s1 = 1;
        #200;
        $display("PASS: tb_blinky initialized");
        $finish;
    end
endmodule

