// reset_gen.v
// Bộ tạo tín hiệu reset đồng bộ: trễ khởi động (Power-on Reset) và nút nhấn S1
// Tang Nano 20K: btn_s1 tích cực mức thấp (nhấn nút = 0)
`timescale 1ns / 1ps

module reset_gen #(
    parameter POR_CYCLES = 64
)(
    input  wire clk,
    input  wire btn_s1,
    output wire rst_n
);

    // Đồng bộ hoá nút nhấn btn_s1 qua 2 tầng flip-flop
    reg btn_s1_sync1 = 1'b0;
    reg btn_s1_sync2 = 1'b0;

    always @(posedge clk) begin
        btn_s1_sync1 <= btn_s1;
        btn_s1_sync2 <= btn_s1_sync1;
    end

    // Bộ đếm power-on reset
    reg [7:0] por_cnt = 8'd0;
    reg por_done = 1'b0;

    always @(posedge clk) begin
        if (!por_done) begin
            if (por_cnt < POR_CYCLES) begin
                por_cnt <= por_cnt + 8'd1;
                por_done <= 1'b0;
            end else begin
                por_done <= 1'b1;
            end
        end
    end

    // Tín hiệu resetn chỉ được giải phóng (lên 1) khi POR hoàn tất và nút S1 không bị nhấn (mức 1)
    assign rst_n = por_done & btn_s1_sync2;

endmodule

// bram_mem.v
// Khối BRAM 32 KB (8192 từ 32-bit) dùng chung cho Lệnh và Dữ liệu
// Hỗ trợ ghi từng byte theo mem_wstrb và nạp trước qua $readmemh
`timescale 1ns / 1ps

module bram_mem #(
    parameter WORDS = 8192,           // 8192 * 4 bytes = 32 KB
    parameter HEX_FILE = ""
)(
    input  wire        clk,
    input  wire        rst_n,
    input  wire        mem_valid,
    input  wire [31:0] mem_addr,
    input  wire [31:0] mem_wdata,
    input  wire [3:0]  mem_wstrb,
    output reg         mem_ready,
    output reg  [31:0] mem_rdata
);

    // Mảng bộ nhớ 32-bit
    reg [31:0] mem [0:WORDS-1];

    wire [12:0] word_addr = mem_addr[14:2];

    initial begin
        if (HEX_FILE != "") begin
            $readmemh(HEX_FILE, mem);
        end
    end

    // Giao thức bắt tay: mem_ready trễ 1 chu kỳ clock theo chuẩn synchronous BRAM
    always @(posedge clk) begin
        if (!rst_n) begin
            mem_ready <= 1'b0;
            mem_rdata <= 32'd0;
        end else begin
            mem_ready <= mem_valid && !mem_ready;
            if (mem_valid) begin
                // Đọc đồng bộ
                mem_rdata <= mem[word_addr];

                // Ghi theo byte mask
                if (mem_wstrb[0]) mem[word_addr][ 7: 0] <= mem_wdata[ 7: 0];
                if (mem_wstrb[1]) mem[word_addr][15: 8] <= mem_wdata[15: 8];
                if (mem_wstrb[2]) mem[word_addr][23:16] <= mem_wdata[23:16];
                if (mem_wstrb[3]) mem[word_addr][31:24] <= mem_wdata[31:24];
            end
        end
    end

endmodule

// uart_tx.v
// Bộ phát UART TX: 8N1, mức nghỉ = 1, tham số hoá bộ chia baud theo clock
`timescale 1ns / 1ps

module uart_tx #(
    parameter CLK_FREQ = 27_000_000,
    parameter BAUD     = 115_200
)(
    input  wire       clk,
    input  wire       rst_n,
    input  wire       tx_start,
    input  wire [7:0] tx_data,
    output wire       tx_busy,
    output reg        tx_serial
);

    localparam CLKS_PER_BIT = CLK_FREQ / BAUD;

    localparam STATE_IDLE = 1'b0;
    localparam STATE_TX   = 1'b1;

    reg state;
    reg [15:0] clk_cnt;
    reg [3:0]  bit_idx;
    reg [9:0]  tx_shifter; // {stop_bit(1), data[7:0], start_bit(0)}

    assign tx_busy = (state == STATE_TX);

    always @(posedge clk) begin
        if (!rst_n) begin
            state      <= STATE_IDLE;
            clk_cnt    <= 16'd0;
            bit_idx    <= 4'd0;
            tx_shifter <= 10'h3FF;
            tx_serial  <= 1'b1;
        end else begin
            case (state)
                STATE_IDLE: begin
                    tx_serial <= 1'b1;
                    clk_cnt   <= 16'd0;
                    bit_idx   <= 4'd0;
                    if (tx_start) begin
                        // Khung UART: 1 start bit (0), 8 bit dữ liệu LSB first, 1 stop bit (1)
                        tx_shifter <= {1'b1, tx_data, 1'b0};
                        state      <= STATE_TX;
                    end
                end

                STATE_TX: begin
                    tx_serial <= tx_shifter[0];
                    if (clk_cnt < CLKS_PER_BIT - 1) begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end else begin
                        clk_cnt <= 16'd0;
                        tx_shifter <= {1'b1, tx_shifter[9:1]};
                        if (bit_idx < 4'd9) begin
                            bit_idx <= bit_idx + 4'd1;
                        end else begin
                            state <= STATE_IDLE;
                        end
                    end
                end
            endcase
        end
    end

endmodule

// gpio_led.v
// Thanh ghi điều khiển 6 LED ngoài bo Tang Nano 20K (chân 15-20, tích cực thấp)
`timescale 1ns / 1ps

module gpio_led (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       led_we,
    input  wire [5:0] led_wdata,
    output wire [5:0] led_n
);

    reg [5:0] led_reg;

    always @(posedge clk) begin
        if (!rst_n) begin
            led_reg <= 6'b000000; // Mặc định tắt LED
        end else if (led_we) begin
            led_reg <= led_wdata;
        end
    end

    // LED trên bo Tang Nano 20K tích cực mức thấp (ghi 0 sáng đèn, ghi 1 tắt)
    // Tín hiệu nội bộ led_reg: 1 = BẬT, 0 = TẮT -> xuất ra chân đảo bit: led_n = ~led_reg
    assign led_n = ~led_reg;

endmodule

// bus_interconnect.v
// Bộ giải mã bus và phân nhánh địa chỉ theo kiến trúc PicoRV32 Memory Bus
`timescale 1ns / 1ps

module bus_interconnect (
    input  wire        clk,
    input  wire        rst_n,

    // Giao diện PicoRV32 Bus
    input  wire        cpu_mem_valid,
    input  wire [31:0] cpu_mem_addr,
    input  wire [31:0] cpu_mem_wdata,
    input  wire [3:0]  cpu_mem_wstrb,
    output wire        cpu_mem_ready,
    output reg  [31:0] cpu_mem_rdata,

    // Giao diện BRAM (0x0000_0000 - 0x0000_7FFF)
    output wire        bram_valid,
    input  wire        bram_ready,
    input  wire [31:0] bram_rdata,

    // Giao diện UART (0x1000_0000 & 0x1000_0004)
    output reg         uart_tx_start,
    output wire [7:0]  uart_tx_data,
    input  wire        uart_busy,

    // Giao diện LED (0x2000_0000)
    output reg         led_we,
    output wire [5:0]  led_wdata
);

    // Phân vùng địa chỉ
    wire sel_bram    = (cpu_mem_addr[31:15] == 17'h00000);             // 0x0000_0000 - 0x0000_7FFF (32 KB)
    wire sel_uart_tx = (cpu_mem_addr == 32'h1000_0000);                // Ghi byte UART TX
    wire sel_uart_st = (cpu_mem_addr == 32'h1000_0004);                // Đọc trạng thái UART (bit 0 = busy)
    wire sel_led     = (cpu_mem_addr == 32'h2000_0000);                // Ghi 6 bit LED

    assign bram_valid = cpu_mem_valid && sel_bram;

    assign uart_tx_data = cpu_mem_wdata[7:0];
    assign led_wdata    = cpu_mem_wdata[5:0];

    // Tạo ready 1 chu kỳ cho toàn bộ các thiết bị ngoại vi MMIO và vùng địa chỉ không hợp lệ
    reg mmio_ready;
    always @(posedge clk) begin
        if (!rst_n) begin
            mmio_ready    <= 1'b0;
            uart_tx_start <= 1'b0;
            led_we        <= 1'b0;
        end else begin
            uart_tx_start <= 1'b0;
            led_we        <= 1'b0;
            mmio_ready    <= cpu_mem_valid && !sel_bram && !mmio_ready;

            if (cpu_mem_valid && !mmio_ready) begin
                if (sel_uart_tx && |cpu_mem_wstrb) begin
                    uart_tx_start <= 1'b1;
                end
                if (sel_led && |cpu_mem_wstrb) begin
                    led_we <= 1'b1;
                end
            end
        end
    end

    // Ghép tín hiệu cpu_mem_ready
    assign cpu_mem_ready = sel_bram ? bram_ready : mmio_ready;

    // Ghép dữ liệu cpu_mem_rdata
    always @(*) begin
        if (sel_bram) begin
            cpu_mem_rdata = bram_rdata;
        end else if (sel_uart_st) begin
            cpu_mem_rdata = {31'd0, uart_busy};
        end else begin
            // Địa chỉ không hợp lệ hoặc thanh ghi chỉ ghi -> đọc ra 0 chống treo
            cpu_mem_rdata = 32'd0;
        end
    end

endmodule

// soc_top.v
// Khối đỉnh toàn SoC Bài 1 cho bo Sipeed Tang Nano 20K (Gowin GW2AR-LV18QN88C8)
`timescale 1ns / 1ps

module soc_top #(
    parameter CLK_FREQ = 27_000_000,
    parameter BAUD     = 115_200,
    parameter HEX_FILE = "firmware.hex"
)(
    input  wire       clk,
    input  wire       btn_s1,
    output wire       uart_tx,
    output wire [5:0] led
);

    // Khối Reset đồng bộ kết hợp Power-on Reset và nút S1
    wire rst_n;
    reset_gen #(
        .POR_CYCLES(64)
    ) u_reset_gen (
        .clk(clk),
        .btn_s1(btn_s1),
        .rst_n(rst_n)
    );

    // Tín hiệu bus PicoRV32
    wire        cpu_trap;
    wire        cpu_mem_valid;
    wire        cpu_mem_instr;
    wire        cpu_mem_ready;
    wire [31:0] cpu_mem_addr;
    wire [31:0] cpu_mem_wdata;
    wire [3:0]  cpu_mem_wstrb;
    wire [31:0] cpu_mem_rdata;

    // Lõi PicoRV32 (RV32I_Zicsr)
    picorv32 #(
        .ENABLE_COUNTERS   (1),
        .ENABLE_COUNTERS64 (1),
        .ENABLE_MUL        (0),
        .ENABLE_DIV        (0),
        .ENABLE_FAST_MUL   (0),
        .ENABLE_PCPI       (0),
        .COMPRESSED_ISA    (0),
        .PROGADDR_RESET    (32'h0000_0000),
        .STACKADDR         (32'h0000_8000)   // Đỉnh 32 KB BRAM
    ) u_cpu (
        .clk         (clk),
        .resetn      (rst_n),
        .trap        (cpu_trap),
        .mem_valid   (cpu_mem_valid),
        .mem_instr   (cpu_mem_instr),
        .mem_ready   (cpu_mem_ready),
        .mem_addr    (cpu_mem_addr),
        .mem_wdata   (cpu_mem_wdata),
        .mem_wstrb   (cpu_mem_wstrb),
        .mem_rdata   (cpu_mem_rdata)
    );

    // Tín hiệu kết nối ngoại vi
    wire        bram_valid;
    wire        bram_ready;
    wire [31:0] bram_rdata;

    wire        uart_tx_start;
    wire [7:0]  uart_tx_data;
    wire        uart_busy;

    wire        led_we;
    wire [5:0]  led_wdata;

    // Bộ giải mã bus MMIO
    bus_interconnect u_bus (
        .clk           (clk),
        .rst_n         (rst_n),
        .cpu_mem_valid (cpu_mem_valid),
        .cpu_mem_addr  (cpu_mem_addr),
        .cpu_mem_wdata (cpu_mem_wdata),
        .cpu_mem_wstrb (cpu_mem_wstrb),
        .cpu_mem_ready (cpu_mem_ready),
        .cpu_mem_rdata (cpu_mem_rdata),

        .bram_valid    (bram_valid),
        .bram_ready    (bram_ready),
        .bram_rdata    (bram_rdata),

        .uart_tx_start (uart_tx_start),
        .uart_tx_data  (uart_tx_data),
        .uart_busy     (uart_busy),

        .led_we        (led_we),
        .led_wdata     (led_wdata)
    );

    // Bộ nhớ BRAM 32 KB
    bram_mem #(
        .WORDS    (8192),
        .HEX_FILE (HEX_FILE)
    ) u_bram (
        .clk       (clk),
        .rst_n     (rst_n),
        .mem_valid (bram_valid),
        .mem_addr  (cpu_mem_addr),
        .mem_wdata (cpu_mem_wdata),
        .mem_wstrb (cpu_mem_wstrb),
        .mem_ready (bram_ready),
        .mem_rdata (bram_rdata)
    );

    // Bộ phát UART TX
    uart_tx #(
        .CLK_FREQ (CLK_FREQ),
        .BAUD     (BAUD)
    ) u_uart_tx (
        .clk       (clk),
        .rst_n     (rst_n),
        .tx_start  (uart_tx_start),
        .tx_data   (uart_tx_data),
        .tx_busy   (uart_busy),
        .tx_serial (uart_tx)
    );

    // Điều khiển 6 LED ngoài
    gpio_led u_gpio_led (
        .clk       (clk),
        .rst_n     (rst_n),
        .led_we    (led_we),
        .led_wdata (led_wdata),
        .led_n     (led)
    );

endmodule

/* linker.ld
 * Bố cục bộ nhớ cho PicoRV32 trên Tang Nano 20K
 * BRAM 32 KB bắt đầu từ địa chỉ 0x00000000 (anh cho, chưa có tài liệu)
 */

OUTPUT_ARCH(riscv)
ENTRY(_start)

MEMORY
{
    BRAM (rwx) : ORIGIN = 0x00000000, LENGTH = 32K
}

SECTIONS
{
    .text : {
        . = ALIGN(4);
        *(.init)
        *(.text)
        *(.text.*)
        . = ALIGN(4);
        _etext = .;
    } > BRAM

    .rodata : {
        . = ALIGN(4);
        *(.rodata)
        *(.rodata.*)
        *(.srodata)
        *(.srodata.*)
        . = ALIGN(4);
    } > BRAM

    .data : {
        . = ALIGN(4);
        *(.data)
        *(.data.*)
        *(.sdata)
        *(.sdata.*)
        . = ALIGN(4);
        _edata = .;
    } > BRAM

    .bss : {
        . = ALIGN(4);
        _sbss = .;
        *(.bss)
        *(.bss.*)
        *(.sbss)
        *(.sbss.*)
        *(COMMON)
        . = ALIGN(4);
        _ebss = .;
    } > BRAM

    /* Đỉnh ngăn xếp ở cuối bộ nhớ BRAM 32 KB */
    _stack_top = ORIGIN(BRAM) + LENGTH(BRAM);
}

/* main.c
 * Chương trình bare-metal Bài 1 chạy trên lõi PicoRV32 (Tang Nano 20K)
 * In chuỗi "Hello from PicoRV32 on Tang Nano 20K, cycle=<số>\r\n"
 * mỗi khoảng 1 giây (đo bằng rdcycle, 27 000 000 chu kỳ) và đảo LED.
 */

#include <stdint.h>

// Địa chỉ MMIO ngoại vi (anh cho, chưa có tài liệu)
#define REG_UART_DATA   (*(volatile uint32_t *)0x10000000)
#define REG_UART_STATUS (*(volatile uint32_t *)0x10000004)
#define REG_LED         (*(volatile uint32_t *)0x20000000)

#ifdef SIM
#define CYCLE_DELAY 1000ULL
#else
#define CYCLE_DELAY 27000000ULL // 1 giây tại 27 MHz (anh cho, chưa có tài liệu)
#endif

// Đọc bộ đếm chu kỳ 64-bit qua lệnh CSR rdcycle / rdcycleh
static inline uint64_t read_cycle(void) {
    uint32_t high0, low, high1;
    do {
        __asm__ volatile ("rdcycleh %0" : "=r"(high0));
        __asm__ volatile ("rdcycle  %0" : "=r"(low));
        __asm__ volatile ("rdcycleh %0" : "=r"(high1));
    } while (high0 != high1);
    return (((uint64_t)high0) << 32) | low;
}

// Gửi một ký tự qua UART TX (chờ busy = 0)
void uart_putc(char c) {
    while (REG_UART_STATUS & 1) {
        // Chờ UART sẵn sàng
    }
    REG_UART_DATA = (uint32_t)(uint8_t)c;
}

// Gửi một chuỗi qua UART TX
void uart_puts(const char *s) {
    while (*s) {
        uart_putc(*s++);
    }
}

// In số nguyên không dấu dạng chuỗi (chia nhị phân không phụ thuộc libgcc)
void print_u64(uint64_t val) {
    char buf[24];
    int idx = 0;
    if (val == 0) {
        uart_putc('0');
        return;
    }
    while (val > 0) {
        uint64_t q = 0;
        uint64_t r = 0;
        for (int i = 63; i >= 0; i--) {
            r = (r << 1) | ((val >> i) & 1);
            if (r >= 10) {
                r -= 10;
                q |= (1ULL << i);
            }
        }
        buf[idx++] = '0' + (char)r;
        val = q;
    }
    while (idx > 0) {
        uart_putc(buf[--idx]);
    }
}

int main(void) {
    uint8_t led_state = 0x01;
    REG_LED = led_state;

    uint64_t last_cycle = read_cycle();

    while (1) {
        uint64_t current_cycle = read_cycle();
        if (current_cycle - last_cycle >= CYCLE_DELAY) {
            last_cycle = current_cycle;

            // In chuỗi định dạng
            uart_puts("Hello from PicoRV32 on Tang Nano 20K, cycle=");
            print_u64(current_cycle);
            uart_puts("\r\n");

            // Đảo LED
            led_state ^= 0x01;
            REG_LED = led_state;
        }
    }

    return 0;
}

// uart_rx_model.v
// Bộ thu giải mã UART mô hình phục vụ testbench tự động
`timescale 1ns / 1ps

module uart_rx_model #(
    parameter CLK_FREQ = 27_000_000,
    parameter BAUD     = 115_200
)(
    input  wire       clk,
    input  wire       rst_n,
    input  wire       rx_serial,
    output reg        rx_valid,
    output reg  [7:0] rx_byte
);

    localparam CLKS_PER_BIT = CLK_FREQ / BAUD;

    localparam STATE_IDLE  = 2'd0;
    localparam STATE_START = 2'd1;
    localparam STATE_DATA  = 2'd2;
    localparam STATE_STOP  = 2'd3;

    reg [1:0]  state;
    reg [15:0] clk_cnt;
    reg [2:0]  bit_idx;
    reg [7:0]  rx_shifter;

    // Lọc khử metastability
    reg rx_sync1, rx_sync2;
    always @(posedge clk) begin
        rx_sync1 <= rx_serial;
        rx_sync2 <= rx_sync1;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            state      <= STATE_IDLE;
            clk_cnt    <= 16'd0;
            bit_idx    <= 3'd0;
            rx_shifter <= 8'd0;
            rx_valid   <= 1'b0;
            rx_byte    <= 8'd0;
        end else begin
            rx_valid <= 1'b0;

            case (state)
                STATE_IDLE: begin
                    clk_cnt <= 16'd0;
                    bit_idx <= 3'd0;
                    if (!rx_sync2) begin // Cạnh xuống start bit
                        state <= STATE_START;
                    end
                end

                STATE_START: begin
                    // Lấy mẫu ở giữa bit start
                    if (clk_cnt == (CLKS_PER_BIT / 2)) begin
                        if (!rx_sync2) begin
                            clk_cnt <= 16'd0;
                            state   <= STATE_DATA;
                        end else begin
                            state   <= STATE_IDLE; // Nhiễu giả
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end

                STATE_DATA: begin
                    if (clk_cnt == CLKS_PER_BIT - 1) begin
                        clk_cnt <= 16'd0;
                        rx_shifter[bit_idx] <= rx_sync2;
                        if (bit_idx == 3'd7) begin
                            state <= STATE_STOP;
                        end else begin
                            bit_idx <= bit_idx + 3'd1;
                        end
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end

                STATE_STOP: begin
                    if (clk_cnt == CLKS_PER_BIT - 1) begin
                        clk_cnt  <= 16'd0;
                        state    <= STATE_IDLE;
                        rx_byte  <= rx_shifter;
                        rx_valid <= 1'b1;
                        // In ký tự trực tiếp ra màn hình console mô phỏng
                        $write("%c", rx_shifter);
                        $fflush();
                    end else begin
                        clk_cnt <= clk_cnt + 16'd1;
                    end
                end
            endcase
        end
    end

endmodule

// tb_soc.v
// Testbench tự kiểm tra toàn SoC Bài 1
// Tự động in PASS khi nhận đúng chuỗi ít nhất 2 lần, FAIL sau thời gian giới hạn
`timescale 1ns / 1ps

module tb_soc;

    reg clk;
    reg btn_s1;
    wire uart_tx_line;
    wire [5:0] leds;

    // Chu kỳ 27 MHz: T ~ 37.037 ns -> nửa chu kỳ 18.518 ns
    initial begin
        clk = 1'b0;
        forever #18.518 clk = ~clk;
    end

    // Nút S1 tích cực mức thấp (mặc định không nhấn = 1)
    initial begin
        btn_s1 = 1'b1;
    end

    // Khởi tạo SoC
    soc_top #(
        .CLK_FREQ (27_000_000),
        .BAUD     (115_200),
        .HEX_FILE ("firmware.hex")
    ) u_dut (
        .clk     (clk),
        .btn_s1  (btn_s1),
        .uart_tx (uart_tx_line),
        .led     (leds)
    );

    // Bộ thu UART mô hình
    wire       rx_valid;
    wire [7:0] rx_byte;

    uart_rx_model #(
        .CLK_FREQ (27_000_000),
        .BAUD     (115_200)
    ) u_rx (
        .clk       (clk),
        .rst_n     (1'b1),
        .rx_serial (uart_tx_line),
        .rx_valid  (rx_valid),
        .rx_byte   (rx_byte)
    );

    // Giám sát chuỗi nhận được
    reg [8*40-1:0] shift_window = 0;
    integer match_count = 0;

    always @(posedge clk) begin
        if (rx_valid) begin
            shift_window <= {shift_window[8*39-1:0], rx_byte};
            // Kiểm tra khớp chuỗi tiền tố cốt lõi "Hello from PicoRV32 on Tang Nano 20K"
            if ({shift_window[8*34-1:0], rx_byte} == "Hello from PicoRV32 on Tang Nano 20K") begin
                match_count <= match_count + 1;
                $display("\n[TB] Phat hien chuoi lan thu %0d tai thoi diem %0t ns", match_count + 1, $time);
                if (match_count + 1 >= 2) begin
                    $display("\n==========================================");
                    $display("  KET QUA MO PHONG: PASS");
                    $display("  Da nhan dung chuoi it nhat 2 lan!");
                    $display("==========================================\n");
                    $finish;
                end
            end
        end
    end

    // Giới hạn thời gian (Timeout guard)
    initial begin
        // Trong chế độ SIM (hằng số delay 1000 chu kỳ), chuỗi in ra rất nhanh (~100-200 us mỗi chuỗi)
        // Thiết lập timeout 20 ms (20,000,000 ns) đủ dồi dào
        #20000000;
        $display("\n==========================================");
        $display("  KET QUA MO PHONG: FAIL");
        $display("  Het thoi gian cho (Timeout)! So lan nhan: %0d", match_count);
        $display("==========================================\n");
        $finish;
    end

endmodule

