/* bai2/sw/linker.ld
 * Bố cục bộ nhớ cho Bài 2 trên BRAM Tang Nano 20K
 * Dung lượng BRAM: 32 KB (0x00000000 - 0x00007FFF)
 */

OUTPUT_ARCH(riscv)
ENTRY(_start)

MEMORY
{
    BRAM (rwx) : ORIGIN = 0x00000000, LENGTH = 32K
}

SECTIONS
{
    .text : {
        . = ALIGN(4);
        *(.init)
        *(.text)
        *(.text.*)
        . = ALIGN(4);
        _etext = .;
    } > BRAM

    .rodata : {
        . = ALIGN(4);
        *(.rodata)
        *(.rodata.*)
        *(.srodata)
        *(.srodata.*)
        . = ALIGN(4);
    } > BRAM

    .data : {
        . = ALIGN(4);
        *(.data)
        *(.data.*)
        *(.sdata)
        *(.sdata.*)
        . = ALIGN(4);
        _edata = .;
    } > BRAM

    .bss : {
        . = ALIGN(4);
        _sbss = .;
        *(.bss)
        *(.bss.*)
        *(.sbss)
        *(.sbss.*)
