        . = ALIGN(4);
        _ebss = .;
    } > BRAM

    /* Stack đặt ở đỉnh BRAM, nở xuống dưới */
    .stack (NOLOAD) : {
        . = ALIGN(16);
        _stack_bottom = .;
        . = ORIGIN(BRAM) + LENGTH(BRAM);
        _stack_top = .;
        __stack = .;
    } > BRAM
}

