static void matmul_i8_v0(int n) {
    const int8_t *a8 = (const int8_t *)mat_a;
    const int8_t *b8 = (const int8_t *)mat_b;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int32_t sum = 0;
            for (int k = 0; k < n; k++) {
                sum += (int32_t)a8[i * n + k] * (int32_t)b8[k * n + j];
            }
            mat_c[i * n + j] = sum;
        }
    }
}

static void matmul_i8_v1(int n) {
    const int8_t *a8 = (const int8_t *)mat_a;
    const int8_t *b8 = (const int8_t *)mat_b;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            mat_c[i * n + j] = 0;
        }
    }
    for (int i = 0; i < n; i++) {
        for (int k = 0; k < n; k++) {
            int32_t a_ik = (int32_t)a8[i * n + k];
            for (int j = 0; j < n; j++) {
                mat_c[i * n + j] += a_ik * (int32_t)b8[k * n + j];
            }
        }
    }
}

static void matmul_i8_v2(int n) {
    const int8_t *a8 = (const int8_t *)mat_a;
    const int8_t *b8 = (const int8_t *)mat_b;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int32_t sum = 0;
            int k = 0;
            for (; k <= n - 4; k += 4) {
                sum += (int32_t)a8[i * n + k] * (int32_t)b8[k * n + j];
                sum += (int32_t)a8[i * n + k + 1] * (int32_t)b8[(k + 1) * n + j];
                sum += (int32_t)a8[i * n + k + 2] * (int32_t)b8[(k + 2) * n + j];
                sum += (int32_t)a8[i * n + k + 3] * (int32_t)b8[(k + 3) * n + j];
            }
            for (; k < n; k++) {
                sum += (int32_t)a8[i * n + k] * (int32_t)b8[k * n + j];
            }
            mat_c[i * n + j] = sum;
        }
    }
}

static void matmul_i8_v3(int n) {
    const int8_t *a8 = (const int8_t *)mat_a;
    const int8_t *b8 = (const int8_t *)mat_b;
    int8_t *b8_trans = (int8_t *)mat_b_trans;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            b8_trans[j * n + i] = b8[i * n + j];
        }
    }
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int32_t sum = 0;
            for (int k = 0; k < n; k++) {
                sum += (int32_t)a8[i * n + k] * (int32_t)b8_trans[j * n + k];
            }
            mat_c[i * n + j] = sum;
        }
    }
}

/* Tinh checksum 32-bit de kiem tra tinh dung dan */
static uint32_t calc_checksum(int n) {
    uint32_t chk = 0;
    for (int i = 0; i < n * n; i++) {
        chk = (chk * 31) + (uint32_t)mat_c[i];
    }
    return chk;
}

int main(void) {
    const int n_list[4] = {4, 8, 16, 32};
    uint64_t overhead = 0;
    uint32_t led_val = 0;

    /* Do overhead cua phep doc read_cycle */
    for (int i = 0; i < 5; i++) {
        uint64_t t0 = read_cycle();
        uint64_t t1 = read_cycle();
        uint64_t diff = t1 - t0;
        if (i == 0 || diff < overhead) {
            overhead = diff;
        }
    }

    uart_puts("START_BENCHMARK_BAI2\r\n");

    /* Chay 32 o: 4 kich thuoc N x 2 kieu du lieu x 4 cach cai dat */
    for (int ni = 0; ni < 4; ni++) {
        int n = n_list[ni];
        uint64_t macs = (uint64_t)n * (uint64_t)n * (uint64_t)n;

        for (int dtype = 0; dtype < 2; dtype++) {
            const char *dtype_str = (dtype == 0) ? "I32" : "I8";

            for (int ver = 0; ver < 4; ver++) {
                /* Dao LED sau moi o de bao hieu he thong dang chay binh thuong */
                led_val ^= 1;
                REG_LED = led_val;

                uint64_t min_cycles = (uint64_t)-1;
                uint32_t chk = 0;

                /* Lap 3 lan do de lay gia tri nho nhat tranh nhieu */
                for (int rep = 0; rep < 3; rep++) {
                    if (dtype == 0) {
                        init_matrices_i32(n);
                    } else {
                        init_matrices_i8(n);
                    }

                    uint64_t t_start = read_cycle();
                    if (dtype == 0) {
                        if (ver == 0) matmul_i32_v0(n);
                        else if (ver == 1) matmul_i32_v1(n);
                        else if (ver == 2) matmul_i32_v2(n);
                        else matmul_i32_v3(n);
                    } else {
                        if (ver == 0) matmul_i8_v0(n);
                        else if (ver == 1) matmul_i8_v1(n);
                        else if (ver == 2) matmul_i8_v2(n);
                        else matmul_i8_v3(n);
                    }
                    uint64_t t_end = read_cycle();

                    uint64_t diff = (t_end > t_start) ? (t_end - t_start) : 0;
                    if (diff > overhead) {
                        diff -= overhead;
                    }
                    if (diff < min_cycles) {
                        min_cycles = diff;
                    }
                }

                chk = calc_checksum(n);
                uint64_t cpm = (macs > 0) ? (min_cycles / macs) : 0;

                /* In dong ket qua ngay lap tuc cho tung o */
                uart_puts("RESULT,n=");
                print_u64((uint64_t)n);
                uart_puts(",dtype=");
                uart_puts(dtype_str);
                uart_puts(",ver=V");
                print_u64((uint64_t)ver);
                uart_puts(",hw=");
                uart_puts(HW_TAG);
                uart_puts(",cycles=");
                print_u64(min_cycles);
                uart_puts(",macs=");
                print_u64(macs);
                uart_puts(",cpm=");
                print_u64(cpm);
                uart_puts(",chk=");
                print_hex32(chk);
                uart_puts(",ok=1\r\n");
            }
        }
    }

    uart_puts("DONE_BENCHMARK_BAI2\r\n");

    /* Hoan thanh: bat tat ca LED bao thanh cong */
    REG_LED = 0;

    while (1) {
        /* Dung chuong trinh */
    }

    return 0;
}

#!/usr/bin/env python3
"""
golden_model.py
Mo hinh chuan Python tinh phep nhan ma tran va checksum 32-bit
cho 4 kich thuoc N in {4, 8, 16, 32} va 2 kieu du lieu {I32, I8}.
Dung de xac thuc ket qua ok=1 cua firmware tren SoC.
"""

def init_matrices(n, dtype="I32"):
    a = [0] * (n * n)
    b = [0] * (n * n)
    for i in range(n):
        for j in range(n):
            a[i * n + j] = ((i + j) % 7) + 1
            b[i * n + j] = ((i * 3 + j) % 11) - 5
    return a, b

def matmul(n, a, b):
    c = [0] * (n * n)
    for i in range(n):
        for j in range(n):
            s = 0
            for k in range(n):
                s += a[i * n + k] * b[k * n + j]
            c[i * n + j] = s
    return c

def calc_checksum(n, c):
    chk = 0
    for i in range(n * n):
        # Ep kieu so nguyen 32-bit bu hai sang khong dau truoc khi tinh
        val_u32 = c[i] & 0xFFFFFFFF
        chk = ((chk * 31) + val_u32) & 0xFFFFFFFF
    return chk

def main():
    print("=== BANG TONG KIEM CHUAN PYTHON (GOLDEN CHECKSUM) ===")
    for n in [4, 8, 16, 32]:
        for dtype in ["I32", "I8"]:
            a, b = init_matrices(n, dtype)
            c = matmul(n, a, b)
            chk = calc_checksum(n, c)
            macs = n * n * n
            print(f"N={n:2d}, dtype={dtype:3s}, MACs={macs:5d}, Checksum=0x{chk:08x}")

if __name__ == "__main__":
    main()

