`timescale 1ns / 1ps

module tb_soc;

    reg clk;
    reg btn_s1;
    wire uart_tx_line;
    wire [5:0] leds;

    // Chu ky 27 MHz
    initial begin
        clk = 1'b0;
        forever #18.518 clk = ~clk;
    end

    initial begin
        btn_s1 = 1'b1;
    end

    // DUT SoC
    soc_top #(
        .CLK_FREQ (27000000),
        .BAUD     (115200),
        .HEX_FILE ("firmware.hex")
    ) u_dut (
        .clk     (clk),
        .btn_s1  (btn_s1),
        .uart_tx (uart_tx_line),
        .led     (leds)
    );

    // Bo thu UART mo hinh
    wire       rx_valid;
    wire [7:0] rx_byte;

    uart_rx_model #(
        .CLK_FREQ (27000000),
        .BAUD     (115200)
    ) u_rx (
        .clk       (clk),
        .rst_n     (1'b1),
        .rx_serial (uart_tx_line),
        .rx_valid  (rx_valid),
        .rx_byte   (rx_byte)
    );

    // In tung byte UART va bat chuoi ket thuc
    reg [8*20-1:0] shift_reg = 0;

    always @(posedge clk) begin
        if (rx_valid) begin
            $write("%c", rx_byte);
            $fflush();
            shift_reg <= {shift_reg[8*19-1:0], rx_byte};
            if ({shift_reg[8*18-1:0], rx_byte} == "DONE_BENCHMARK_BAI2") begin
                $display("\n==========================================");
                $display("  KET QUA MO PHONG BAI 2: PASS");
                $display("  Da hoan thanh toan bo cac o do!");
                $display("==========================================\n");
                $finish;
            end
        end
    end

    // Gioi han thoi gian mo phong
    initial begin
        #500_000_000; // 500 ms mo phong
        $display("\n==========================================");
        $display("  KET QUA MO PHONG BAI 2: FAIL (Timeout)");
        $display("==========================================\n");
        $finish;
    end

endmodule

